// writeFlatConfig marshals the typed per-variant Config struct back to JSON
// and stores each top-level key as a jsontypes.Normalized value in r.Config,
// matching the shape users write in HCL (each map element is a JSON-encoded
// scalar/object). Keys the API omits are dropped from state; keys the API
// normalizes are stored in their normalized form so the next plan sees no
// diff. If the API returned no active variant (should not happen), the
// existing plan-derived r.Config is preserved.
func (r *ObservabilityDestinationResourceModel) writeFlatConfig(typedConfig any) diag.Diagnostics {
	var diags diag.Diagnostics
	if typedConfig == nil {
		return diags
	}
	raw, err := json.Marshal(typedConfig)
	if err != nil {
		diags.AddError(
			"Config Serialization Error",
			fmt.Sprintf("Failed to serialize API-returned destination config into flat map form: %v", err),
		)
		return diags
	}
	var asMap map[string]json.RawMessage
	if err := json.Unmarshal(raw, &asMap); err != nil {
		diags.AddError(
			"Config Serialization Error",
			fmt.Sprintf("Failed to decode API-returned destination config into flat map form: %v", err),
		)
		return diags
	}
	flat := make(map[string]jsontypes.Normalized, len(asMap))
	for k, v := range asMap {
		if string(v) == "null" {
			// JSON null fields (e.g. optional fields the API omits as null)
			// are dropped rather than stored as a "null" literal, matching
			// the convention that users don't write null values in config.
			continue
		}
		flat[k] = jsontypes.NewNormalizedValue(string(v))
	}
	r.Config = flat
	return diags
}
